275	/* A segment between two vertices already in pixel coordinates, as a quad. An
276	 * end with a butt or round cap is lengthened enough to cover the pixel at the
277	 * vertex (half a pixel on an axis-aligned line; up to 0.71 on a diagonal when
278	 * the width is even and the vertex is a pixel corner). A projecting cap is
279	 * half the width past the vertex. An end that meets another segment
280	 * (STROKE_NO_CAP) is not lengthened at all. */
281	static void segment_quad(Canvas *c, vec2 a, vec2 b, int cap1, int cap2, int w,
282	                         uint16_t colour) {
283	  const float dx = b.x - a.x, dy = b.y - a.y;
284	  const float len = sqrtf(dx * dx + dy * dy);
285	  if (len < 0.001f) return;
286	  const float ux = dx / len, uy = dy / len;
287	  const float half = (float)w / 2.0f;
288	  const float pixel_along = (0.5f - centre_offset(w)) * (ux + uy);
289	  /* A butt cap must reach the vertex pixel (at least half a pixel). A
290	   * projecting cap reaches half the width past the vertex, which covers it,
291	   * plus the vertex pixel's offset when that is past the vertex. */
292	  const float e1 = cap1 == STROKE_NO_CAP     ? 0.0f
293	                   : cap1 == CapProjecting   ? half + fmaxf(0.0f, -pixel_along)
294	                                             : fmaxf(0.5f, -pixel_along);
295	  const float e2 = cap2 == STROKE_NO_CAP     ? 0.0f
296	                   : cap2 == CapProjecting   ? half + fmaxf(0.0f, pixel_along)
297	                                             : fmaxf(0.5f, pixel_along);
298	  const float nx = -uy * half, ny = ux * half;
299	  const vec2 p = {a.x - ux * e1, a.y - uy * e1};
300	  const vec2 q = {b.x + ux * e2, b.y + uy * e2};
301	  const float quad[4][2] = {
302	      {p.x + nx, p.y + ny}, {q.x + nx, q.y + ny}, {q.x - nx, q.y - ny},
303	      {p.x - nx, p.y - ny}};
304	  fill_convex(c, quad, 4, colour);
305	}
