357	/* The corner between a segment arriving along d1 and one leaving along d2
358	 * (unit vectors), at vertex (ix, iy). */
359	static void join_at(Canvas *c, int ix, int iy, vec2 d1, vec2 d2, int w,
360	                    int style, uint16_t colour) {
361	  const float dot = d1.x * d2.x + d1.y * d2.y;
362	  const float cross = d1.x * d2.y - d1.y * d2.x;
363	  if (fabsf(cross) < 1e-4f && dot > 0) return;
364	  if (style == JoinRound) {
365	    disc(c, ix, iy, w, colour);
366	    return;
367	  }
368	  const vec2 v = vertex(ix, iy, w);
369	  const float half = (float)w / 2.0f;
370	  const float side = cross > 0 ? -1.0f : 1.0f;
371	  const vec2 n1 = {-d1.y * side, d1.x * side}, n2 = {-d2.y * side, d2.x * side};
372	  const vec2 p1 = {v.x + n1.x * half, v.y + n1.y * half};
373	  const vec2 p2 = {v.x + n2.x * half, v.y + n2.y * half};
374	  /* Xlib's miter limit of 10: the miter is longer than ten widths when the
375	   * segments meet at less than about 11.5 degrees, i.e. dot < -0.98. */
376	  if (style == JoinMiter && dot >= -0.98f) {
377	    const float k = half / (1.0f + dot);
378	    const float quad[4][2] = {{v.x, v.y},
379	                              {p1.x, p1.y},
380	                              {v.x + (n1.x + n2.x) * k, v.y + (n1.y + n2.y) * k},
381	                              {p2.x, p2.y}};
382	    fill_convex(c, quad, 4, colour);
383	    return;
384	  }
385	  const float tri[3][2] = {{v.x, v.y}, {p1.x, p1.y}, {p2.x, p2.y}};
386	  fill_convex(c, tri, 3, colour);
387	}
